if(PHP_SAPI!=='cli')exit('CLI uniquement.');require_once __DIR__.'/../includes/app.php';$email=$argv[1]??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)){fwrite(STDERR,"Usage: php scripts/create_admin.php admin@exemple.com\n");exit(1);}echo 'Mot de passe administrateur (12 caractères minimum) : ';if(function_exists('shell_exec')){$password=rtrim((string)fgets(STDIN),"\r\n");}else{$password=rtrim((string)fgets(STDIN),"\r\n");}if(strlen($password)<12){fwrite(STDERR,"Mot de passe trop court.\n");exit(1);}db()->prepare('INSERT INTO admins(email,password_hash)VALUES(?,?)ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash)')->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);echo "Administrateur créé : $email\n";
